use arboard::{Clipboard, ImageData as ArboardImageData};

/// 从剪贴板读取图像
#[tauri::command]
fn read_clipboard_image() -> Result<ImageData, String> {
    let mut clipboard = Clipboard::new()
        .map_err(|e| format!("无法访问剪贴板: {}", e))?;

    let image = clipboard
        .get_image()
        .map_err(|e| format!("剪贴板中没有图像: {}", e))?;

    Ok(ImageData {
        width: image.width,
        height: image.height,
        bytes: image.bytes.to_vec(),
    })
}
```

#### 2.3 图像保存

**文件**: `src-tauri/src/lib.rs`

```rust
use image::{RgbaImage, ImageBuffer};
use std::fs;

/// 保存图像到本地
#[tauri::command]
fn save_image(
    app: tauri::AppHandle,
    image_data: Vec<u8>,
    width: u32,
    height: u32,
    todo_id: String,
) -> Result<String, String> {
    // 获取应用数据目录
    let app_data_dir = app.path()
        .app_data_dir()
        .map_err(|e| format!("无法获取应用数据目录: {}", e))?;

    // 创建images子目录
    let images_dir = app_data_dir.join("images");
    fs::create_dir_all(&images_dir)
        .map_err(|e| format!("无法创建图像目录: {}", e))?;

    // 生成文件名
    let timestamp = chrono::Local::now().format("%Y%m%d_%H%M%S").to_string();
    let filename = format!("{}_{}.png", todo_id, timestamp);
    let file_path = images_dir.join(&filename);

    // 将字节数据转换为图像
    let img = RgbaImage::from_raw(width, height, image_data)
        .ok_or("无效的图像数据")?;

    // 保存图像
    img.save(&file_path)
        .map_err(|e| format!("保存图像失败: {}", e))?;

    Ok(file_path.to_string_lossy().to_string())
}
```

#### 2.4 AI图像处理

**文件**: `src-tauri/src/ai_service.rs` (新建)

```rust
use serde::{Serialize, Deserialize};
use std::path::Path;
use std::fs;
use base64::{Engine as _, engine::general_purpose};

#[derive(Debug, Serialize, Deserialize)]
pub struct ProcessingResult {
    pub summary: String,
    pub raw_text: String,
    pub method: String,
}

/// OpenAI API请求结构
#[derive(Debug, Serialize)]
struct OpenAIRequest {
    model: String,
    messages: Vec<OpenAIMessage>,
    max_tokens: u32,
}

#[derive(Debug, Serialize)]
struct OpenAIMessage {
    role: String,
    content: Vec<OpenAIContent>,
}

#[derive(Debug, Serialize)]
#[serde(tag = "type")]
enum OpenAIContent {
    #[serde(rename = "text")]
    Text { text: String },
    #[serde(rename = "image_url")]
    ImageUrl { image_url: ImageUrl },
}

#[derive(Debug, Serialize)]
struct ImageUrl {
    url: String,
}

#[derive(Debug, Deserialize)]
struct OpenAIResponse {
    choices: Vec<OpenAIChoice>,
}

#[derive(Debug, Deserialize)]
struct OpenAIChoice {
    message: OpenAIResponseMessage,
}

#[derive(Debug, Deserialize)]
struct OpenAIResponseMessage {
    content: String,
}

/// 使用OpenAI处理图像
pub async fn process_with_openai(
    image_path: &str,
    api_key: &str,
    locale: &str,
) -> Result<ProcessingResult, String> {
    // 读取图像文件
    let image_bytes = fs::read(image_path)
        .map_err(|e| format!("读取图像失败: {}", e))?;

    // 转换为base64
    let base64_image = general_purpose::STANDARD.encode(&image_bytes);
    let data_url = format!("data:image/png;base64,{}", base64_image);

    // 构建提示词
    let prompt = if locale == "zh-CN" {
        "请分析这张图片,提取其中的文本内容,并用1-2句话总结图片的主要内容。\
         请按以下格式返回:\n\
         提取的文本: [这里是OCR提取的所有文本]\n\
         摘要: [这里是1-2句话的摘要]"
    } else {
        "Please analyze this image, extract the text content, and summarize the main content in 1-2 sentences.\
         Please return in the following format:\n\
         Extracted text: [All OCR extracted text here]\n\
         Summary: [1-2 sentence summary here]"
    };

    // 构建请求
    let request = OpenAIRequest {
        model: "gpt-4.1".to_string(),
        messages: vec![OpenAIMessage {
            role: "user".to_string(),
            content: vec![
                OpenAIContent::Text {
                    text: prompt.to_string(),
                },
                OpenAIContent::ImageUrl {
                    image_url: ImageUrl {
                        url: data_url,
                    },
                },
            ],
        }],
        max_tokens: 500,
    };

    // 发送请求
    let client = reqwest::Client::new();
    let response = client
        .post("https://api.openai.com/v1/chat/completions")
        .header("Authorization", format!("Bearer {}", api_key))
        .header("Content-Type", "application/json")
        .json(&request)
        .timeout(std::time::Duration::from_secs(30))
        .send()
        .await
        .map_err(|e| format!("API请求失败: {}", e))?;

    if !response.status().is_success() {
        let status = response.status();
        let error_text = response.text().await.unwrap_or_default();
        return Err(format!("API返回错误 {}: {}", status, error_text));
    }

    let api_response: OpenAIResponse = response
        .json()
        .await
        .map_err(|e| format!("解析响应失败: {}", e))?;

    // 解析响应
    let content = api_response.choices
        .first()
        .ok_or("API响应为空")?
        .message
        .content
        .clone();

    // 解析提取的文本和摘要
    let (raw_text, summary) = parse_ai_response(&content, locale);

    Ok(ProcessingResult {
        summary,
        raw_text,
        method: "ai".to_string(),
    })
}

/// 解析AI响应
fn parse_ai_response(content: &str, locale: &str) -> (String, String) {
    let (text_marker, summary_marker) = if locale == "zh-CN" {
        ("提取的文本:", "摘要:")
    } else {
        ("Extracted text:", "Summary:")
    };

    let mut raw_text = String::new();
    let mut summary = String::new();

    if let Some(text_start) = content.find(text_marker) {
        let text_content = &content[text_start + text_marker.len()..];
        if let Some(summary_start) = text_content.find(summary_marker) {
            raw_text = text_content[..summary_start].trim().to_string();
            summary = text_content[summary_start + summary_marker.len()..].trim().to_string();
        } else {
            raw_text = text_content.trim().to_string();
        }
    }

    // 如果解析失败,使用整个内容作为摘要
    if summary.is_empty() {
        summary = content.trim().to_string();
    }

    (raw_text, summary)
}

/// 使用本地OCR处理(后备方案)
pub fn process_with_local_ocr(
    image_path: &str,
) -> Result<ProcessingResult, String> {
    // TODO: 实现本地OCR
    // 这里可以使用tesseract-rs或leptess

    // 临时实现:返回占位符
    Ok(ProcessingResult {
        summary: "图像内容(OCR处理中)".to_string(),
        raw_text: "".to_string(),
        method: "ocr".to_string(),
    })
}
```

#### 2.5 主处理命令

**文件**: `src-tauri/src/lib.rs`

```rust
mod ai_service;

use ai_service::{process_with_openai, process_with_local_ocr};

/// 处理图像(AI识别)
#[tauri::command]
async fn process_image_ai(
    app: tauri::AppHandle,
    image_path: String,
    locale: String,
) -> Result<ImageProcessingResult, String> {
    // 从设置中读取API密钥
    let store = app.store("settings.json")
        .map_err(|e| format!("无法访问设置: {}", e))?;

    let api_key = if let Some(settings) = store.get("settings") {
        settings.get("openaiApiKey")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
    } else {
        None
    };

    // 如果有API密钥,使用AI处理
    if let Some(key) = api_key {
        match process_with_openai(&image_path, &key, &locale).await {
            Ok(result) => {
                return Ok(ImageProcessingResult {
                    success: true,
                    summary: Some(result.summary),
                    raw_text: Some(result.raw_text),
                    method: result.method,
                    error: None,
                });
            }
            Err(e) => {
                eprintln!("AI处理失败,回退到本地OCR: {}", e);
                // 继续尝试本地OCR
            }
        }
    }

    // 使用本地OCR作为后备
    match process_with_local_ocr(&image_path) {
        Ok(result) => {
            Ok(ImageProcessingResult {
                success: true,
                summary: Some(result.summary),
                raw_text: Some(result.raw_text),
                method: result.method,
                error: None,
            })
        }
        Err(e) => {
            Ok(ImageProcessingResult {
                success: false,
                summary: None,
                raw_text: None,
                method: "none".to_string(),
                error: Some(e),
            })
        }
    }
}

/// 清理待办事项关联的图像
#[tauri::command]
fn cleanup_todo_image(
    app: tauri::AppHandle,
    image_path: String,
) -> Result<(), String> {
    let path = Path::new(&image_path);
    if path.exists() {
        fs::remove_file(path)
            .map_err(|e| format!("删除图像失败: {}", e))?;
    }
    Ok(())
}
```

