fn validate_image_path(path: &str, app_data_dir: &Path) -> Result<(), String> {
    let path = Path::new(path);

    // 确保路径在应用数据目录内
    if !path.starts_with(app_data_dir) {
        return Err("无效的图像路径".to_string());
    }

